 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def edge_bar(line):
        vals = [v for v in line if v != bg]
        if not vals or len(set(vals)) != 1:
            return None
        color = vals[0]
        pos = [i for i, v in enumerate(line) if v == color]
        if pos != list(range(pos[0], pos[-1] + 1)):
            return None
        return pos[0], pos[-1] + 1, color

    left = edge_bar([grid[r][0] for r in range(h)])
    right = edge_bar([grid[r][-1] for r in range(h)])
    if not left or not right or left[1] - left[0] != right[1] - right[0] or left[2] != right[2]:
        return out

    # Markers within either edge bar's row range project to the matching row
    # within the opposite bar; their row rays extend toward their own edge.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color == bg:
                continue
            if left[0] <= r < left[1]:
                mapped = right[0] + (r - left[0])
                for cc in range(1, w - 1):
                    out[mapped][cc] = color
                for cc in range(1, c):
                    out[r][cc] = color
                out[r][c] = 4
            elif right[0] <= r < right[1]:
                mapped = left[0] + (r - right[0])
                for cc in range(1, w - 1):
                    out[mapped][cc] = color
                for cc in range(c + 1, w - 1):
                    out[r][cc] = color
                out[r][c] = 4
    return out


if __name__ == '__main__':
